class Solution {
public:
    TreeNode* tail = nullptr;
    TreeNode* head = nullptr;
    void walk(TreeNode* node) {
        if (!node) return;
        walk(node->left);
        node->left = nullptr;
        if (tail) tail->right = node;
        else head = node;
        tail = node;
        walk(node->right);
    }
    TreeNode* increasingBST(TreeNode* root) {
        walk(root);
        return head;
    }
};
